button{appearance:none;border:2px solid var(--ink);background:var(--paper);color:var(--ink);font:800 .76rem "Avenir Next","Trebuchet MS",sans-serif;letter-spacing:.04em;padding:10px 12px;cursor:pointer;box-shadow:3px 3px 0 var(--ink);transition:.12s}button:hover,button:focus-visible{transform:translate(-1px,-1px);box-shadow:5px 5px 0 var(--ink);outline:0}button.active{background:var(--blue);color:white}.palette-button{width:44px;height:36px;padding:0;position:relative;overflow:hidden}.palette-button:after{content:"";position:absolute;inset:0 0 0 50%;background:var(--swatch)}.palette-button[data-palette=orange]{background:#f45124;--swatch:#1657bc}.palette-button[data-palette=plum]{background:#8d245e;--swatch:#b7d735}.palette-button[data-palette=teal]{background:#087f79;--swatch:#ff7361}.grid-pick{display:grid;grid-template-columns:repeat(3,38px);gap:5px}.grid-pick button{width:38px;height:38px;padding:0;box-shadow:none;background:#e8dfc9}.grid-pick button.active{background:var(--orange)}
.poster-shell{padding:18px;background:#dbcda9}.poster-topline{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px;font-size:.65rem;letter-spacing:.14em;text-transform:uppercase;font-weight:900}.poster{--p1:#f45124;--p2:#1657bc;position:relative;aspect-ratio:4/5;min-height:580px;overflow:hidden;background:var(--paper);border:3px solid var(--ink);isolation:isolate}.poster:after{content:"";position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,transparent 0 8px,rgba(23,42,70,.026) 9px);z-index:10}.poster-grid{position:absolute;inset:0;display:grid;grid-template:repeat(3,1fr)/repeat(3,1fr);z-index:9;pointer-events:none;opacity:0;transition:.2s}.poster.show-grid .poster-grid{opacity:1}.poster-grid i{border-right:1px dashed rgba(23,42,70,.42);border-bottom:1px dashed rgba(23,42,70,.42)}.art-window{position:absolute;width:54%;height:62%;left:40%;top:8%;overflow:hidden;border:4px solid var(--ink);transform:rotate(2deg);transition:.45s cubic-bezier(.2,.8,.2,1);z-index:2;background:var(--p2)}.art-window img{width:100%;height:100%;object-fit:cover;display:block;mix-blend-mode:multiply}
.poster[data-point="0"] .art-window{left:5%;top:5%}.poster[data-point="1"] .art-window{left:23%;top:5%}.poster[data-point="2"] .art-window{left:41%;top:5%}.poster[data-point="3"] .art-window{left:5%;top:20%}.poster[data-point="4"] .art-window{left:23%;top:20%}.poster[data-point="5"] .art-window{left:41%;top:20%}.poster[data-point="6"] .art-window{left:5%;top:33%}.poster[data-point="7"] .art-window{left:23%;top:33%}.poster[data-point="8"] .art-window{left:41%;top:33%}.disc{position:absolute;width:33%;aspect-ratio:1;border-radius:50%;background:var(--p1);left:-7%;top:13%;z-index:1}.bar{position:absolute;width:68%;height:11%;background:var(--p2);right:-20%;bottom:18%;transform:rotate(-9deg);z-index:1}.micro{position:absolute;left:7%;top:6%;font-weight:900;letter-spacing:.2em;font-size:.6rem;text-transform:uppercase;z-index:4}.headline{position:absolute;left:7%;bottom:8%;width:73%;z-index:5;font-family:"Cooper Black","Bookman Old Style",serif;font-size:clamp(2.6rem,6vw,6.3rem);line-height:.78;letter-spacing:-.06em;text-transform:uppercase;overflow-wrap:anywhere;transition:.2s}.headline span{color:var(--p1)}.poster[data-size=quiet] .headline{font-size:clamp(2rem,4vw,4.2rem);width:58%}.poster[data-size=loud] .headline{font-size:clamp(3.4rem,7.5vw,7.8rem);width:88%}.poster-foot{position:absolute;right:5%;bottom:4%;writing-mode:vertical-rl;font-size:.56rem;letter-spacing:.18em;font-weight:900;text-transform:uppercase;z-index:5}.seal{position:absolute;right:4%;top:4%;width:70px;aspect-ratio:1;border:3px solid var(--ink);border-radius:50%;background:var(--acid);z-index:6;display:grid;place-items:center;text-align:center;font-size:.52rem;font-weight:900;line-height:1.1;transform:rotate(12deg)}
.actions{display:flex;gap:10px;margin-top:16px;flex-wrap:wrap}.actions button{flex:1;min-width:140px}.actions .primary{background:var(--orange);color:white}.scorecard{margin-top:50px;border-top:4px solid var(--ink);padding-top:34px;display:none}.scorecard.visible{display:block;animation:rise .5s both}.score-grid{display:grid;grid-template-columns:1fr 1.4fr;gap:45px}.score{width:190px;aspect-ratio:1;border:4px solid var(--ink);border-radius:50%;background:var(--acid);display:grid;place-items:center;text-align:center;transform:rotate(-4deg);box-shadow:10px 10px 0 var(--orange)}.score strong{font:900 5rem/.8 "Bodoni 72",Georgia,serif}.score span{display:block;font-size:.65rem;letter-spacing:.16em;text-transform:uppercase}.verdict h2{font-family:"Cooper Black","Bookman Old Style",serif;font-size:clamp(2.5rem,5vw,5rem);line-height:.9;margin:0 0 16px}.verdict p{font:1.1rem/1.65 Georgia,serif}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:18px}.check{border:2px solid var(--ink);padding:13px;font-size:.72rem;font-weight:900;text-transform:uppercase;background:var(--paper)}.check:before{content:"✓";display:block;font-size:1.35rem;color:var(--orange);margin-bottom:5px}.source{margin:80px auto 20px;border:3px solid var(--ink);background:var(--blue);color:white;padding:28px;max-width:850px;box-shadow:8px 8px 0 var(--orange);transform:rotate(-.5deg);font:1.05rem/1.55 Georgia,serif}.source strong{font-family:"Cooper Black","Bookman Old Style",serif;font-size:1.35rem}.source a{text-decoration-thickness:2px;text-underline-offset:4px}.footer{text-align:center;text-transform:uppercase;letter-spacing:.16em;font-size:.65rem;font-weight:900;padding:20px 20px 50px}
@keyframes rise{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}}@media(max-width:820px){.mast{grid-template-columns:1fr;padding-top:90px}.hero-art{width:min(76vw,400px);margin-top:10px}.intro,.desk,.score-grid{grid-template-columns:1fr}.panel{position:relative;top:auto}.poster{min-height:0}.checks{grid-template-columns:1fr}.brief-number{font-size:5rem}.hero-copy h1 span{margin-left:0}.nav{align-items:flex-start}.nav span:last-child{max-width:145px;text-align:right}.intro{gap:15px}}@media(max-width:480px){h1{font-size:4rem}.mast{padding-left:18px;padding-right:18px}.hero-art:before{left:-8px}.poster-shell{padding:10px}.seal{width:54px}.panel{padding:17px}.headline{font-size:2.5rem!important}.poster[data-size=loud] .headline{font-size:3.15rem!important}.poster[data-size=quiet] .headline{font-size:2rem!important}.art-window{border-width:3px}.source{margin-top:55px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important;transition:none!important}}
</style></head><body>
<header class="mast"><nav class="nav"><a href="./">← Chloe reads Jon</a><span class="issue">Creative field exercise · 01</span></nav><div class="hero-copy"><span class="kicker">Vancouver bureau of better ideas</span><h1>The Joy <span>Department</span></h1><p class="lede">A tiny art-direction desk for making one cheerful idea look intentional. Choose your contrast, place the energy, and give the words enough nerve to earn their ink.</p><div class="stamp"><i>☺</i> Your brief: create a smile without drawing one</div></div><figure class="hero-art"><img src="joy-department-poster.webp" alt="A joyful geometric cut-paper studio illustration in orange and blue"></figure></header>
<div class="marquee" aria-hidden="true"><div>IDEAS NEED SHAPE <span>●</span> BEAUTY IS USEFUL <span>▲</span> MAKE THE EYE DANCE <span>■</span> IDEAS NEED SHAPE <span>●</span> BEAUTY IS USEFUL <span>▲</span> MAKE THE EYE DANCE <span>■</span></div></div>
<main><section class="intro"><div><span class="eyebrow">Incoming creative brief</span><h2>Direct the<br>delight.</h2></div><p><span class="brief-number">01</span>A neighbourhood festival needs a poster that feels bold, warm, and impossible to ignore. Use the commissioned collage, complementary colour, a 3×3 grid, and a headline with some actual backbone.</p></section>
<section class="desk" aria-label="Interactive poster studio"><aside class="panel"><h3>Art director’s knobs</h3>
<div class="control"><div class="control-title"><b>1 · The words</b><em>Say one thing</em></div><div class="choices" id="words"><button class="active" data-word="Make|room|for joy">Make room</button><button data-word="Hello|good|neighbour">Neighbour</button><button data-word="A bright|idea|arrives">Bright idea</button></div></div>
<div class="control"><div class="control-title"><b>2 · Contrast</b><em>Opposites hum</em></div><div class="choices" id="palettes"><button class="palette-button active" data-palette="orange" aria-label="Orange and blue"></button><button class="palette-button" data-palette="plum" aria-label="Plum and lime"></button><button class="palette-button" data-palette="teal" aria-label="Teal and coral"></button></div></div>
<div class="control"><div class="control-title"><b>3 · Focal point</b><em>Use the thirds</em></div><div class="grid-pick" id="gridPick" aria-label="Choose one of nine focal points"></div></div>
<div class="control"><div class="control-title"><b>4 · Volume</b><em>Whisper or holler</em></div><div class="choices" id="sizes"><button data-size="quiet">Quiet</button><button class="active" data-size="balanced">Balanced</button><button data-size="loud">Loud</button></div></div><div class="choices"><button id="gridToggle">Show the grid</button></div></aside>
<div><div class="poster-shell"><div class="poster-topline"><span>Live proof · move 04</span><span id="status">Composition settling…</span></div><div class="poster" id="poster" data-point="2" data-size="balanced"><div class="poster-grid" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="disc"></div><div class="bar"></div><div class="micro">Surrey · Saturday · everybody welcome</div><div class="art-window"><img src="joy-department-poster.webp" alt="Geometric studio artwork used as the poster's focal image"></div><div class="headline" id="headline">Make<br><span>room</span><br>for joy</div><div class="seal">GOOD<br>IDEAS<br>INSIDE</div><div class="poster-foot">A small civic experiment in cheer</div></div></div><div class="actions"><button id="shuffle">Surprise me</button><button class="primary" id="present">Present to the client →</button></div></div></section>
<section class="scorecard" id="scorecard" aria-live="polite"><div class="score-grid"><div class="score"><div><strong id="score">92</strong><span>Joy units</span></div></div><div class="verdict"><span class="eyebrow">The client has leaned forward</span><h2 id="verdict">This has a pulse.</h2><p id="note">The contrast catches the eye, the thirds keep it moving, and the headline knows why it came to work. Print it before somebody asks for a beige version.</p><div class="checks"><div class="check">Clear hierarchy</div><div class="check">Useful tension</div><div class="check">One loud idea</div></div></div></div></section>
<aside class="source"><strong>Why this exists</strong><br>Inspired by Jon’s <a href="https://jona.ca/2008/12/my-creative-bro-designer-dave-aquino.html">My creative bro: designer Dave Aquino</a>, and Dave’s lovely ambition to “create smiles and joy through stunning, unique ideas.”</aside></main><footer class="footer">Filed by the Joy Department · Please leave the colours where you found them</footer>
<script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],poster=$("#poster"),headline=$("#headline"),status=$("#status"),palettes={orange:["#f45124","#1657bc"],plum:["#8d245e","#b7d735"],teal:["#087f79","#ff7361"]};function activate(g,b){$$(g+" button").forEach(x=>x.classList.remove("active"));b.classList.add("active")}function settle(){status.textContent="Ink still warm";status.animate([{opacity:.25},{opacity:1}],{duration:450})}
$("#words").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;activate("#words",b);const p=b.dataset.word.split("|");headline.innerHTML=p[0]+"<br><span>"+p[1]+"</span><br>"+p[2];settle()});$("#palettes").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;activate("#palettes",b);const p=palettes[b.dataset.palette];poster.style.setProperty("--p1",p[0]);poster.style.setProperty("--p2",p[1]);settle()});$("#sizes").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;activate("#sizes",b);poster.dataset.size=b.dataset.size;settle()});
for(let i=0;i<9;i++){const b=document.createElement("button");b.setAttribute("aria-label","Focal point "+(i+1));if(i===2)b.className="active";b.onclick=()=>{$$("#gridPick button").forEach(x=>x.classList.remove("active"));b.classList.add("active");poster.dataset.point=i;settle()};$("#gridPick").append(b)}$("#gridToggle").onclick=e=>{poster.classList.toggle("show-grid");e.currentTarget.textContent=poster.classList.contains("show-grid")?"Hide the grid":"Show the grid"};$("#shuffle").onclick=()=>{const r=s=>{const a=$$(s+" button");a[Math.floor(Math.random()*a.length)].click()};r("#words");r("#palettes");r("#sizes");const g=$$("#gridPick button");g[Math.floor(Math.random()*g.length)].click()};
$("#present").onclick=()=>{const p=+poster.dataset.point,s=poster.dataset.size;let n=Math.min(97,82+([0,2,6,8].includes(p)?7:2)+(s==="loud"?4:s==="balanced"?2:0));$("#score").textContent=n;$("#verdict").textContent=n>92?"Ship this glorious thing.":n>87?"This has a pulse.":"This is charmingly unruly.";$("#note").textContent=n>92?"Strong contrast, decisive type, and a focal point with excellent manners. The client has used the phrase “exactly what I didn’t know I wanted.”":n>87?"The contrast catches the eye, the thirds keep it moving, and the headline knows why it came to work. Print it before somebody asks for a beige version.":"There is joy here, plus the useful little wobble that proves a human made choices. One more nudge would be fussing. Call it done.";$("#scorecard").classList.add("visible");$("#scorecard").scrollIntoView({behavior:"smooth",block:"center"})};
</script></body></html>